package com.cyberpath.learning;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.media.*;
import android.media.session.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.util.UUID;

/** Explicit local playback only. Foreground lifetime belongs to the media session. */
public final class LocalAudioService extends Service {
 private static final String CHANNEL="lw-listening";private static final int NOTICE=925;
 private static volatile LocalAudioService instance;private static volatile String error="";
 private static volatile String published="{}";
 private MediaPlayer player;private MediaSession session;private AudioManager manager;private AudioFocusRequest focus;
 private String profile="",title="",token="";private File source;private boolean ready,requested,loop,seeking;private long start,end;private final Handler handler=new Handler(Looper.getMainLooper());
 private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 public static JSONObject prepare(Context c,String data,String title,String profile)throws Exception{
  ProfileFiles.requireActive(c,profile);if(data==null||!data.matches("(?s)data:audio/[A-Za-z0-9.+-]+;base64,.*")||data.length()>40000000||title==null||title.length()>240)throw new IOException("Choose local audio smaller than 25 MB.");
  File folder=new File(c.getCacheDir(),"local-listening");if(!folder.exists()&&!folder.mkdirs())throw new IOException("Audio could not be prepared.");String token=UUID.randomUUID().toString();File file=new File(folder,profile+"-"+token+".audio");byte[] bytes=android.util.Base64.decode(data.substring(data.indexOf(',')+1),android.util.Base64.DEFAULT);if(bytes.length>25000000)throw new IOException("Audio is too large.");try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}long duration;MediaMetadataRetriever reader=new MediaMetadataRetriever();try{reader.setDataSource(file.getAbsolutePath());duration=Long.parseLong(reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));}catch(Exception e){file.delete();throw new IOException("This audio format could not be read on this phone.");}finally{reader.release();}
  // Unplayed prepared files expire; an active player's source is retained.
  File[] files=folder.listFiles();if(files!=null)for(File old:files)if(old.lastModified()<System.currentTimeMillis()-86400000L&&(instance==null||!old.equals(instance.source)))old.delete();
  return new JSONObject().put("token",token).put("duration",duration/1000d);
 }
 public static JSONObject status(String profile){try{JSONObject value=new JSONObject(published);if(!profile.equals(value.optString("profile")))return new JSONObject().put("playing",false).put("seconds",0).put("duration",0).put("error","");value.remove("profile");return value;}catch(Exception e){return new JSONObject();}}
 private void snapshot(boolean stopped){try{boolean playing=false;long duration=0;try{if(ready&&player!=null){playing=!stopped&&player.isPlaying();duration=player.getDuration();}}catch(Exception ignored){}published=new JSONObject().put("profile",profile).put("token",token).put("playing",playing).put("seconds",stopped?0:position()/1000d).put("duration",duration/1000d).put("stopped",stopped).put("seeking",seeking).put("error",error).toString();}catch(Exception ignored){}}
 public static void stop(Context c){c.stopService(new Intent(c,LocalAudioService.class));error="";}
 @Override public void onCreate(){super.onCreate();instance=this;manager=getSystemService(AudioManager.class);session=new MediaSession(this,"LW local listening");session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onStop(){finish();}public void onSeekTo(long ms){seek(ms);}public void onSkipToNext(){seek(position()+10000);}public void onSkipToPrevious(){seek(position()-10000);}});session.setActive(true);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setOnAudioFocusChangeListener(change->{if(change<0)pause();},handler).build();if(Build.VERSION.SDK_INT>=33)registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(CHANNEL,"Local listening",NotificationManager.IMPORTANCE_LOW));}
 private PendingIntent action(String op){return PendingIntent.getService(this,op.hashCode(),new Intent(this,LocalAudioService.class).setAction(op).putExtra("profile",profile),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private Notification notification(){boolean playing=ready&&player.isPlaying();PendingIntent open=PendingIntent.getActivity(this,926,new Intent(this,MainActivity.class).putExtra("lwRoute","listening"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,CHANNEL).setSmallIcon(R.drawable.notification_leaf).setContentTitle(title.isEmpty()?"Local listening":title).setContentText(playing?"Playing offline":"Paused").setContentIntent(open).setVisibility(Notification.VISIBILITY_PRIVATE).setOnlyAlertOnce(true).setOngoing(playing).addAction(new Notification.Action.Builder(null,playing?"Pause":"Play",action(playing?"pause":"play")).build()).addAction(new Notification.Action.Builder(null,"Stop",action("stop")).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1)).build();}
 private void publish(){snapshot(false);try{session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putLong(MediaMetadata.METADATA_KEY_DURATION,ready?player.getDuration():0).build());session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS).setState(ready&&player.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,position(),1).build());getSystemService(NotificationManager.class).notify(NOTICE,notification());}catch(Exception ignored){}}
 private long position(){try{return ready?player.getCurrentPosition():0;}catch(Exception e){return 0;}}
 private void seek(long ms){if(!ready)return;seeking=true;player.seekTo((int)Math.max(0,Math.min(player.getDuration(),ms)),MediaPlayer.SEEK_CLOSEST);publish();}
 private void play(){requested=true;if(!ready||seeking)return;if(manager.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){error="Another audio activity is using the speaker. Tap Play again.";pause();return;}if(loop&&(position()<start||position()>=end))seek(start);if(seeking)return;player.start();handler.removeCallbacks(tick);handler.post(tick);publish();}
 private void pause(){requested=false;if(ready&&player.isPlaying())player.pause();if(manager!=null&&focus!=null)manager.abandonAudioFocusRequest(focus);publish();handler.removeCallbacks(expire);handler.postDelayed(expire,600000);}
 private final Runnable expire=()->{if(!requested)finish();};
 private final Runnable tick=new Runnable(){public void run(){if(ready&&requested){snapshot(false);if(loop&&!seeking&&position()>=end)seek(start);handler.postDelayed(this,100);}}};
 private void finish(){stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i==null){finish();return START_NOT_STICKY;}try{String who=i.getStringExtra("profile");ProfileFiles.requireActive(this,who);String op=i.getAction();if("stop".equals(op)){finish();return START_NOT_STICKY;}if("load".equals(op)){profile=who;String next=i.getStringExtra("token");if(next==null||!next.matches("[a-f0-9-]{36}"))throw new IOException("Invalid local recording.");title=i.getStringExtra("title");if(title==null||title.length()>240)title="Local listening";token=next;source=new File(new File(getCacheDir(),"local-listening"),profile+"-"+token+".audio");if(!source.isFile())throw new IOException("Open this recording again.");if(player!=null)player.release();ready=false;seeking=false;requested=true;player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setDataSource(source.getAbsolutePath());loop=i.getBooleanExtra("loop",false);start=i.getLongExtra("start",0);end=i.getLongExtra("end",0);if(Build.VERSION.SDK_INT>=29)startForeground(NOTICE,notification(),ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(NOTICE,notification());player.setOnPreparedListener(p->{ready=true;if(loop&&(end>p.getDuration()||start<0||end-start<100)){error="Adjust the loop to fit this recording.";loop=false;}seek(i.getLongExtra("seek",0));if(requested)play();else publish();});player.setOnSeekCompleteListener(p->{seeking=false;if(requested&&!p.isPlaying())play();else publish();});player.setOnCompletionListener(p->{if(loop&&requested){seek(start);play();}else pause();});player.setOnErrorListener((p,a,b)->{error="This recording could not play on this phone.";finish();return true;});error="";player.prepareAsync();snapshot(false);}
   else if(profile.equals(who)){if("play".equals(op))play();else if("pause".equals(op))pause();else if("seek".equals(op))seek(i.getLongExtra("seek",0));else if("loop".equals(op)){long a=i.getLongExtra("start",0),b=i.getLongExtra("end",0);boolean on=i.getBooleanExtra("loop",false);if(a<0||b-a<100||ready&&b>player.getDuration())throw new IOException("Choose a valid loop range.");start=a;end=b;loop=on;}}else finish();
  }catch(Exception e){error=e.getMessage();finish();}return START_NOT_STICKY;}
 @Override public void onTaskRemoved(Intent root){finish();}
 @Override public void onDestroy(){snapshot(true);ready=false;handler.removeCallbacksAndMessages(null);try{unregisterReceiver(noisy);}catch(Exception ignored){}if(player!=null){player.release();player=null;}if(manager!=null&&focus!=null)manager.abandonAudioFocusRequest(focus);if(session!=null){session.setActive(false);session.release();}if(source!=null)source.delete();instance=null;super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
